// mineral fluorescence: the real short-wave UV colours (calcite, willemite, fluorite,
// scheelite, hyalite, aragonite) — this is why the anchor style is a cabinet, not a party
const MIN_H=[8,108,250,205,90,45], MIN_S=[0.92,0.95,0.74,0.34,0.52,0.36];
const CLB_H=[55,145,320,190,28], DEAD=0.16;

const MAXP=90, MAXM=190;
