  S.seedUsed=P.seed;
  S.pt=[];
  for(let i=0;i<MAXP;i++){
    const nv=5+Math.floor(fr(i*41+9)*4);
    const rr=[];
    for(let j=0;j<nv;j++) rr.push(0.52+fr(i*71+j*13+3)*0.62);
    S.pt.push({
      x: fr(i*3+1), y: fr(i*5+2),
      r: 0.022+Math.pow(fr(i*7+3),1.8)*0.10,
      rot: fr(i*11+4)*6.2832,
      spin: (0.008+fr(i*13+5)*0.030)*(fr(i*17+6)>0.5?1:-1),
      yield: fr(i*19+7)<DEAD ? 0.05+fr(i*23+8)*0.10 : 0.42+fr(i*29+10)*0.62,   // some things just don't glow
      m: Math.floor(fr(i*31+11)*6),
      dx: (fr(i*37+12)-0.5)*0.032, dy: (fr(i*43+13)-0.5)*0.024,
      wr: 0.23+fr(i*47+14)*0.51,
      nv: nv, rr: rr
    });
  }
  S.mt=[];
  for(let i=0;i<MAXM;i++) S.mt.push({
    x: fr(i*53+21), y: fr(i*59+22),
    len: 0.006+Math.pow(fr(i*61+23),2)*0.048,
    ang: fr(i*67+24)*6.2832,
    dr: (0.004+fr(i*71+25)*0.016)*(fr(i*73+26)>0.5?1:-1),
    fall: 0.003+fr(i*79+27)*0.014,
    bow: (fr(i*83+28)-0.5)*1.5,
    yield: 0.35+fr(i*89+29)*0.65,
    m: Math.floor(fr(i*97+30)*6),
    ph: fr(i*101+31)*6.2832
  });
}
const t=K.t*sp;

// ---- where the tube is pointing (incommensurate; act sets the path) ----
let LX, LY, RM=1;
const hx=clp(P.x,-0.2,1.2), hy=clp(P.y,-0.2,1.2);
if(act==='scan'){
  const row=frc(t*0.021), col=frc(t*0.137);
  LX=hx+(col*2-1)*0.46*sw+0.03*Math.sin(t*0.53);
  LY=hy+(row*2-1)*0.34*sw+0.02*Math.sin(t*0.31+1.1);
  RM=0.82;
} else if(act==='hold'){
  LX=hx+0.05*sw*Math.sin(t*0.067)+0.03*sw*Math.sin(t*0.157+2.1);
  LY=hy+0.04*sw*Math.sin(t*0.089+0.7)+0.02*sw*Math.sin(t*0.193+1.4);
  RM=1.22;
} else {
  LX=hx+sw*(0.32*Math.sin(t*0.083)+0.15*Math.sin(t*0.211+1.7)+0.07*Math.sin(t*0.397+0.3));
  LY=hy+sw*(0.22*Math.sin(t*0.061+0.9)+0.11*Math.sin(t*0.163+2.4)+0.05*Math.sin(t*0.311+1.1));
  RM=1;
}
const driftM = act==='hold' ? 7 : act==='scan' ? 1.7 : 1;   // in 'hold' the lamp sits still and the stuff drifts past it instead
const lx=LX*W, ly=LY*Hh;
const R=u*(0.42+0.40*en)*sc*RM*(1+0.07*Math.sin(t*0.127)+0.04*Math.sin(t*0.283+1.9));
const OUT=(0.42+0.78*en)*(0.74+0.5*K.intensity)*(1+A.rms*0.28);
// the tube is a UV-A source: what you see is almost all Stokes-shifted re-emission,
// plus the lamp's weak visible violet tail. So the field itself stays dim and the GLOW does the work.
const uvAt=(px,py)=>{
  const dx=px-lx, dy=py-ly, rn=Math.sqrt(dx*dx+dy*dy)/R;
  return isIns ? clp(1-Math.pow(rn,4.5),0,1)*OUT : clp(1/(1+rn*rn*1.7),0,1)*OUT;
};

// ---- the visible violet tail: broad, additive, sweeping — this is the area element ----
blendMode(ADD);
{
  const vc=rgbs(isNeg?H+8:H, isIns?0.62:isNeg?0.30:0.80, 1, 1);
  const base=rgbs(H-6, 0.86, 1, 1);
  const ga=clp((isNeg?0.28:0.24)*al*(0.4+0.85*en),0,0.32);
  const gr=drawingContext.createRadialGradient(lx,ly,0,lx,ly,Math.max(8,R*(isIns?1.15:2.5)));
  gr.addColorStop(0,vc.replace(/[\d.]+\)$/,ga.toFixed(3)+')'));
  gr.addColorStop(isIns?0.86:0.4,vc.replace(/[\d.]+\)$/,(ga*(isIns?0.9:0.42)).toFixed(3)+')'));
  gr.addColorStop(1,vc.replace(/[\d.]+\)$/,'0)'));
  drawingContext.fillStyle=gr;
  drawingContext.fillRect(0,0,W,Hh);
  // a faint floor of violet so even the unlit corners read as a UV room, never as a spotlight
  drawingContext.fillStyle=base.replace(/[\d.]+\)$/,(clp((isNeg?0.115:0.085)*al*(0.3+0.7*en),0,0.15)).toFixed(3)+')');
  drawingContext.fillRect(0,0,W,Hh);
}
blendMode(BLEND);

// ---- fluorescing bodies: they light up only where the UV lands, in sequence as it sweeps ----
const nP=Math.max(4,Math.round(lrp(10,MAXP,dn)));
if(isNeg) blendMode(BLEND); else blendMode(ADD);
noStroke();
for(let i=0;i<nP;i++){
  const p=S.pt[i];
  const px=(frc(p.x+p.dx*t*driftM)*1.1-0.05)*W;
  const py=(frc(p.y+p.dy*t*driftM)*1.1-0.05)*Hh;
  const uv=uvAt(px,py);
  const gl=clp(uv*p.yield*(0.85+0.3*Math.sin(t*p.wr+p.rot)),0,1.3);
  if(gl<0.02) continue;
  const rad=p.r*u*sc*(0.85+0.25*Math.sin(t*p.wr*0.7+p.x*9));
  const e=clp(gl,0,1);
  let hh,ss,vv,aa;
  if(isClb){ hh=CLB_H[p.m%5]; ss=0.86; vv=lrp(0.35,1,Math.pow(e,0.55)); aa=clp(e*74,0,74); }
