  else if(isNeg){ hh=H+10; ss=lrp(0.35,0.05,e); vv=lrp(0.46,0.03,Math.pow(e,0.5)); aa=clp(28+e*66,0,92); }
  else { hh=MIN_H[p.m]; ss=MIN_S[p.m]*lrp(1.05,0.7,e); vv=lrp(0.30,1,Math.pow(e,0.5)); aa=clp(e*78,0,78); }
  push();
  translate(px,py);
  rotate(p.rot+p.spin*t);
  if(!isNeg&&e>0.34){ drawingContext.shadowBlur=rad*0.55*e; drawingContext.shadowColor=rgbs(hh,ss*0.7,1,0.5*e); }
  fill(hh,ss*100,vv*100,aa*al);
  if(isClb||isIns){
    // soft residue blooms — detergent brightener in cloth, adhesive, salt
    beginShape();
    for(let j=0;j<=p.nv;j++){ const a2=j/p.nv*6.2832, rr=rad*p.rr[j%p.nv]*(1+0.14*Math.sin(a2*3+t*0.4+p.rot)); curveVertex(Math.cos(a2)*rr,Math.sin(a2)*rr); }
    endShape(CLOSE);
  } else {
    // crystal faces — angular, with a brighter cleavage plane catching the light
    beginShape();
    for(let j=0;j<p.nv;j++){ const a2=j/p.nv*6.2832, rr=rad*p.rr[j]; vertex(Math.cos(a2)*rr,Math.sin(a2)*rr); }
    endShape(CLOSE);
