    const my=(frc(m.y+m.fall*t*driftM*1.4+0.03*Math.sin(t*0.7+m.ph))*1.12-0.06)*Hh;
    const uv=uvAt(mx,my);
    const gl=clp(uv*m.yield,0,1.2);
    if(gl<0.05) continue;
    const e=clp(gl,0,1);
    const L=m.len*u*sc*(0.6+0.8*e);
    const a2=m.ang+t*m.dr*3.1+0.5*Math.sin(t*0.63+m.ph);
    let hh,ss;
    if(isClb){ hh=CLB_H[m.m%5]; ss=70; } else if(isIns){ hh=186; ss=10; } else if(isNeg){ hh=H+10; ss=14; } else { hh=MIN_H[m.m]; ss=MIN_S[m.m]*58; }
    stroke(hh,ss,isNeg?lrp(48,4,e):lrp(46,100,Math.pow(e,0.55)),clp((isNeg?40+e*52:12+72*e)*al,0,84));
    strokeWeight(Math.max(0.4,u*0.0011*sc*(0.5+e)));
