// ---- the tube itself: dim, because a UV-A lamp barely shows ----
if(!isNeg&&lx>-R&&lx<W+R&&ly>-R&&ly<Hh+R){
  blendMode(ADD);
  noStroke();
  drawingContext.shadowBlur=u*0.05*sc;
  drawingContext.shadowColor=rgbs(H,0.9,1,0.5);
  fill(H,86,lrp(60,100,en),clp(26*al,0,32));
  push(); translate(lx,ly); rotate(0.4*Math.sin(t*0.13)+0.2*Math.sin(t*0.29+1.2));
  rect(-u*0.10*sc,-u*0.006*sc,u*0.20*sc,u*0.012*sc,u*0.006*sc);
